/* Export surface for libnccl_trace.so. See ibverbs.map for why.
 *
 * The nccl* entries MUST stay global — they ARE the interposition. libnccl's
 * own definitions are weak (NCCL_API under PROFAPI), so a strong definition
 * here wins the symbol for the whole process; hiding one silently hands that
 * call back to NCCL and the table for it is empty rather than absent, which
 * reads as "the workload never called it".
 */
{
  global:
    ncclCommInitRank;
    ncclCommInitRankConfig;
    ncclCommDestroy;
    ncclCommAbort;
    ncclAllReduce;
    ncclBroadcast;
    ncclReduce;
    ncclAllGather;
    ncclReduceScatter;
    ncclSend;
    ncclRecv;
    ncclGroupStart;
    ncclGroupEnd;
    ncclCommWindowRegister;
    ncclCommWindowDeregister;
    ncclDevCommCreate;
    /* Not an interposer — a DATA symbol NCCL dlsym's out of this library after
     * dlopening it by the path in NCCL_PROFILER_PLUGIN. Hiding it does not
     * degrade the capture, it removes the profiler door entirely and silently:
     * NCCL falls through v4 to v3 to v2, finds nothing, logs "is unsupported"
     * at INFO level only, and runs on. See nccl_profiler_plugin.cpp. */
    ncclProfiler_v4;
    comshu_create_provider;
    comshu_abi_version;
  local:
    *;
};
